import * as M from './model.js';
import * as P from './planner.js';
import * as Support from './student-support.js';
export const BOOKS=[
{id:'umbrella',title:'노란 우산의 자리',band:1,chapters:['비가 내리는 아침, 나리는 노란 우산을 폈다. 골목 끝에서 우산이 없는 친구가 보였다. 나리는 우산을 크게 기울였지만 둘의 어깨가 번갈아 젖었다.','두 사람은 빨리 걸을수록 더 젖는다는 것을 알았다. 걸음을 맞추고 우산 손잡이를 함께 잡자 작은 마른 자리가 생겼다. 친구는 자기 가방으로 나리의 공책을 덮어 주었다.','교문 앞에는 또 다른 친구가 있었다. 세 사람이 우산 아래 들어가자 모두 꽉 붙어 서야 했다. 나리는 비를 완전히 피하는 것보다 혼자 남지 않는 것이 좋다고 생각했다.','교실에 도착한 아이들은 젖은 어깨를 닦고 서로의 공책을 펼쳐 주었다. 노란 우산은 말리는 동안에도 세 사람의 자리를 기억하는 것 같았다.'],activity:'함께 쓰기 위해 바꾼 행동을 찾고 우산 속에 넣고 싶은 말을 써요.'},
{id:'seed',title:'느린 씨앗의 하루',band:1,chapters:['화분 세 개에 씨앗을 하나씩 심었다. 첫째 화분과 둘째 화분에서는 싹이 나왔지만 셋째 화분은 조용했다. 도윤이는 흙 속을 꺼내 보고 싶어졌다.','도윤이는 매일 같은 자리에서 화분을 그렸다. 변한 것이 없어 보여도 흙의 색과 잎의 방향은 조금씩 달랐다. 선생님은 보이지 않는 곳에서도 준비가 이어질 수 있다고 말했다.','어느 날 셋째 화분의 흙이 아주 조금 올라왔다. 도윤이는 손으로 도와주려다 멈추었다. 대신 창가의 자리를 비워 주고 기다렸다.','작은 싹이 고개를 내밀었다. 도윤이의 관찰장에는 싹이 없는 날의 그림도 가득했다. 도윤이는 그 그림까지 모두 자람의 기록이라는 것을 알게 되었다.'],activity:'기다리는 동안 할 수 있는 도움을 그림과 한 문장으로 표현해요.'},
{id:'button',title:'굴러간 단추 하나',band:1,chapters:['미술 시간에 소율이의 주머니에서 파란 단추가 굴러갔다. 단추는 누구의 물건인지 모르는 상자 앞에서 멈췄다. 소율이는 다른 물건들도 집을 찾고 싶을 것 같았다.','아이들은 물건의 이름만 적은 표지판을 만들었다. 그런데 작은 장갑 두 개가 서로 닮아 주인을 찾기 어려웠다. 이름 대신 색과 크기, 마지막으로 본 곳도 적어 보기로 했다.','장갑의 주인은 설명을 읽고 찾아왔다. 파란 단추의 주인은 아직 오지 않았다. 소율이는 기다릴 수 있도록 투명한 주머니에 단추를 넣었다.','며칠 뒤 동생이 단추를 찾아왔다. 자기 물건이 아니어도 잘 보관할 수 있다는 말에 소율이는 분실물 상자에 새 이름을 붙였다. 기다리는 물건의 집.'],activity:'분실물을 찾을 수 있는 설명을 쓰고 개인정보 없이 안내판을 만들어요.'},
{id:'shadow',title:'그림자가 쉴 때',band:1,chapters:['운동장의 그림자가 짧아졌다 길어졌다. 서아는 그림자가 자꾸 도망간다고 생각했다. 친구들은 그림자 길이를 신발로 재어 보자고 했다.','아침에 남긴 표시와 점심에 남긴 표시가 달랐다. 아이들은 그림자를 붙잡는 대신 같은 자리에 서 보는 방법을 골랐다.','구름이 해를 가리자 그림자가 흐려졌다. 서아는 그림자가 쉬는 시간이라고 말했다. 친구는 하늘의 빛이 달라졌다고 덧붙였다. 두 생각을 관찰장에 나란히 적었다.','마지막 관찰에서 그림자는 다시 길어졌다. 아이들은 본 것과 상상한 것을 색을 달리해 표시했다. 서아의 그림자는 하루 동안 긴 이야기를 남겼다.'],activity:'실제로 본 장면과 상상한 장면을 구분해 그려요.'},
{id:'alley',title:'우리 골목 시간 상자',band:3,chapters:['골목 도서관을 옮기던 날 낡은 과자 통이 나왔다. 통 안에는 버스표와 사진, 이름 없는 메모가 있었다. 민재는 사진 속 빈터가 지금 놀이터라고 생각했다.','아이들은 사진의 건물 모양과 간판을 지도에서 찾았다. 같은 자리가 맞았지만 사진의 날짜는 알 수 없었다. 오래 살던 이웃에게 물을 질문을 적었다.','이웃은 빈터에서 장이 열리던 때를 기억했다. 다른 이웃은 그곳에서 공을 차던 이야기를 했다. 같은 장소에도 서로 다른 기억이 겹쳐 있었다.','아이들은 현재의 지도와 관찰 기록을 새 상자에 넣었다. 확실히 아는 사실과 더 알아볼 질문을 따로 적었다. 미래의 누군가가 자신의 골목을 발견할 수 있도록.'],activity:'자료의 시기·근거·아직 모르는 점을 나누어 우리 고장의 시간 상자를 구성해요.'},
{id:'post',title:'파도 우체국의 편지',band:3,chapters:['바닷가 우체국에 주소가 지워진 편지가 도착했다. 우체국장은 편지를 함부로 펼치지 않고 겉봉의 작은 등대 그림을 살폈다. 유나는 등대가 두 곳이라는 사실을 떠올렸다.','유나와 친구들은 편지를 대신 읽기보다 보낸 사람을 찾는 안내를 만들었다. 이름과 내용을 모두 공개하지 않고 필요한 단서만 남겼다.','며칠 뒤 한 사람이 자신이 보낸 편지라고 연락했다. 그는 바뀐 주소를 확인해 다시 적었다. 유나는 서둘러 전달하는 일만큼 정확하게 묻는 일이 중요하다고 생각했다.','편지는 제자리를 찾아 떠났다. 아이들은 우체국 벽에 안내문을 붙였다. 마음을 잘 전하려면 상대가 받아 볼 수 있는 길도 함께 살펴야 한다고.'],activity:'등장인물의 선택을 근거로 설명하고 개인정보를 지키는 안내를 써요.'},
{id:'bridge',title:'두 마을의 작은 다리',band:3,chapters:['두 마을 사이의 다리가 고장 나자 아이들의 산책길이 끊겼다. 어른들은 새 다리의 위치를 두고 서로 다른 생각을 내놓았다. 혜원이는 지도를 펴고 의견을 표시했다.','가까운 길을 원하는 사람도 있었고 천천히 걸을 수 있는 넓은 길을 원하는 사람도 있었다. 비가 오면 물이 차는 자리도 있었다. 가장 많은 의견만 세어서는 풀리지 않는 문제였다.','아이들은 필요한 조건을 목록으로 만들었다. 안전하게 건너기, 돌아가는 거리 줄이기, 누구나 이용하기였다. 각 후보지를 같은 조건으로 비교했다.','마을은 전문가의 점검을 받아 다리를 고쳤다. 아이들은 자신들이 결정하지 못한 문제도 기록에 남겼다. 함께 정한다는 것은 이유를 나누고 책임을 이어 가는 일이었다.'],activity:'장소별 장단점을 비교하고 모두가 이용할 수 있는 조건을 제안해요.'},
{id:'sound',title:'소리를 모으는 공책',band:3,chapters:['지안은 학교에서 들리는 소리를 공책에 적었다. 의자 끄는 소리, 종이 넘기는 소리, 모둠에서 웃는 소리는 서로 달랐다. 조용하면 언제나 수업이 잘되는 걸까 궁금해졌다.','말이 없는 모둠에서는 한 친구만 문제를 풀고 있었다. 소리가 큰 모둠에서는 서로 풀이를 설명하고 있었다. 지안은 크기와 함께 무슨 말을 하는지도 기록했다.','아이들은 활동마다 필요한 소리의 약속을 정했다. 혼자 읽을 때와 토론할 때의 기준은 달랐다. 어려우면 도움을 청하는 신호도 만들었다.','공책의 마지막 장에는 가장 작은 소리가 적혔다. 다시 설명해 줄래라는 질문이었다. 지안은 배우는 소리를 듣는 방법이 전보다 많아졌다고 생각했다.'],activity:'소리 크기와 학습 참여를 따로 관찰하고 활동별 소리 약속을 정해요.'},
{id:'tomorrow',title:'내일을 빌리는 가게',band:5,chapters:['골목 끝 가게는 물건 대신 내일의 계획을 빌려 주었다. 가게 주인은 시간을 바꿀 수는 없고 다른 사람의 계획을 읽어 볼 수 있을 뿐이라고 했다. 준서는 가장 바빠 보이는 계획을 골랐다.','계획에는 공부와 운동뿐 아니라 동생을 기다리는 시간, 병원에 갈 가족을 배웅하는 시간이 있었다. 겉으로 보이지 않는 약속이 하루를 채우고 있었다.','준서는 자기 계획에 빈칸이 많다고 부끄러워했다. 그러나 가게 주인은 빈칸에 무엇을 넣고 싶은지 물었다. 준서는 쉬는 시간과 친구의 말을 들을 시간을 적었다.','다음 날 준서는 계획을 돌려주었다. 남의 하루를 그대로 살 수는 없지만 선택의 이유를 더 조심스럽게 물을 수는 있었다. 가게에는 다시 새로운 내일이 놓였다.'],activity:'인물의 선택과 조건을 구분하고 자신의 하루 계획에 필요한 여유를 설명해요.'},
{id:'broadcast',title:'여섯 번째 방송',band:5,chapters:['학급 방송의 대본에는 늘 다섯 사람의 의견만 들어갔다. 방송부는 손을 가장 먼저 드는 사람의 말을 받아 적고 있었다. 예린은 말 대신 그림으로 의견을 낸 친구를 떠올렸다.','팀은 종이 제안함과 짧은 녹음, 그림 설명을 함께 받았다. 비슷해 보이는 의견에도 이유가 달랐다. 대본을 줄이면서 어떤 목소리가 빠지는지 표시했다.','방송 당일 마이크 한 개가 작동하지 않았다. 아이들은 순서를 바꾸고 자막판을 활용했다. 모든 말을 똑같이 크게 하는 대신 들을 수 있는 방법을 더했다.','여섯 번째 방송에는 처음 나서는 친구의 한 문장이 담겼다. 방송이 끝난 뒤 팀은 누가 말했는지만 세지 않았다. 누구의 의견이 실제 계획을 바꾸었는지도 돌아보았다.'],activity:'여러 표현 방법을 반영한 방송안을 만들고 참여 기회가 공정했는지 점검해요.'},
{id:'island-map',title:'지도 밖의 작은 섬',band:5,chapters:['관광 지도에는 섬의 멋진 풍경만 있었다. 주민이 오가는 선착장과 비를 피하는 작은 쉼터는 빠져 있었다. 현우는 누구를 위한 지도인지 질문했다.','친구들은 여행자, 주민, 어린이의 하루 동선을 비교했다. 같은 길이라도 쉬는 곳과 안내 표지가 필요한 지점은 달랐다. 바다와 날씨는 마음대로 지나갈 수 없는 조건이었다.','새 지도에는 보기 좋은 장소와 생활에 필요한 장소를 함께 넣었다. 직접 확인한 정보에는 날짜를 적고 바뀔 수 있는 배편은 확인할 곳을 표시했다.','지도 발표에서 아이들은 빈칸을 숨기지 않았다. 아직 확인하지 못한 정보와 더 들어야 할 주민 의견을 적었다. 지도는 완성된 답보다 함께 고쳐 쓰는 약속에 가까웠다.'],activity:'서로 다른 이용자의 필요를 비교하고 정보의 확인일과 한계를 표시한 지도를 설계해요.'},
{id:'repair-day',title:'고쳐 쓰는 토요일',band:5,chapters:['마을 나눔장터를 준비하던 아이들은 고장 난 물건을 발견했다. 모두 버리는 것과 무조건 고치는 것 사이에서 선택 기준이 필요했다.','팀은 안전하게 쓸 수 있는지, 전문가의 확인이 필요한지, 설명서와 부품이 있는지를 분류했다. 직접 다루면 안 되는 물건은 어른에게 점검을 맡겼다.','장터에서는 물건을 가져오지 않은 친구도 안내와 기록을 맡았다. 교환권과 기부 물품은 장부를 따로 썼다. 많이 가져온 사람이 더 큰 목소리를 얻지는 않았다.','장터가 끝난 뒤 아이들은 남은 물건과 기록을 맞추었다. 고쳐 쓴 것은 물건만이 아니었다. 함께 쓰고 결정하는 방법도 조금 달라져 있었다.'],activity:'물건의 안전·사용 가능성과 자발적 나눔 원칙을 점검하고 교환 장부를 만들어요.'}
];
export const book=id=>BOOKS.find(b=>b.id===id);
export function data(s){return s.libraryLife??={schema:1,stock:Object.fromEntries(BOOKS.map(b=>[b.id,s.students.length+4])),loans:[],classBook:null,reading:{},activities:[],history:[]};}
export function available(s,id){const d=data(s);return (d.stock[id]||0)-d.loans.filter(l=>l.bookId===id&&!l.returned).reduce((n,l)=>n+l.count,0);}
export function lend(s,id,studentId){const d=data(s);if(!book(id)||!s.students.some(x=>x.id===studentId)||available(s,id)<1)return {error:'대출 가능한 책과 학생을 확인해 주세요.'};if(d.loans.some(l=>l.studentId===studentId&&l.bookId===id&&!l.returned))return {error:'같은 책을 이미 빌렸습니다.'};d.loans.push({id:'loan-'+s.day+'-'+d.loans.length,bookId:id,studentId,count:1,day:s.day,due:Math.min(M.demoDays(s)-1,s.day+10),returned:false,extended:false});return {ok:true};}
export function returnLoan(s,id){const l=data(s).loans.find(x=>x.id===id);if(!l||l.returned)return false;l.returned=true;l.returnedAt=M.stamp(s);return true;}
export function extend(s,id){const l=data(s).loans.find(x=>x.id===id);if(!l||l.returned||l.extended)return false;l.due=Math.min(M.demoDays(s)-1,Math.max(s.day,l.due)+5);l.extended=true;return true;}
export function select(s,id){const d=data(s),b=book(id);if(!b)return false;if(d.classBook===id)return {error:'이미 함께 읽고 있는 책입니다.'};if(available(s,id)<s.students.length)return {error:'학급 세트가 부족합니다. 개인 대출 반납 또는 다른 책을 사서와 협의해 주세요.'};for(const l of d.loans.filter(l=>l.studentId==='class'&&!l.returned)){l.returned=true;l.returnedAt=M.stamp(s);}d.classBook=id;d.loans.push({id:'class-set-'+s.day+'-'+d.loans.length,bookId:id,studentId:'class',count:s.students.length,day:s.day,due:Math.min(M.demoDays(s)-1,s.day+25),returned:false,extended:false});d.reading[id]??={chapter:0,students:Object.fromEntries(s.students.map(st=>[st.id,0]))};M.addMessage(s,'grade','이은서 사서교사',`「${b.title}」 학급 세트 ${s.students.length}권을 준비했습니다. 읽은 부분과 학생별 진도는 따로 기록해 주세요.`,{senderId:'librarian',plannerScanned:true});return {ok:true};}
export function readChapter(s){const d=data(s),b=book(d.classBook),r=d.reading[d.classBook],slot=M.currentSlot(s);if(!b||!r||r.chapter>=b.chapters.length)return {error:'읽을 책과 남은 장을 확인해 주세요.'};if(!['classroom','library'].includes(s.room)||slot.kind!=='lesson'||!['국어','창체','바른 생활','슬기로운 생활'].includes(slot.subject)||slot.end-s.minute<30)return {error:'국어·창체·통합교과 수업의 시작 무렵에 교실이나 도서관에서 읽어요.'};const chapter=r.chapter;if(!M.finishLesson(s,slot.subject,0,'온책읽기',slot.period))return {error:'이 수업은 이미 진행했거나 장소를 확인해야 합니다.'};r.chapter++;for(const st of s.students)if(M.isPresent(s,st.id)&&Support.available(s,st.id))r.students[st.id]=Math.max(r.students[st.id]||0,r.chapter);s.lessonResults.at(-1).reading={bookId:b.id,chapter:chapter+1};d.history.push({bookId:b.id,chapter:chapter+1,date:M.stamp(s),day:s.day});return {ok:true,chapter:chapter+1};}
export function support(s,studentId){const d=data(s),r=d.reading[d.classBook],st=s.students.find(x=>x.id===studentId);if(!r||!st||!M.isPresent(s,st.id)||!Support.available(s,st.id)||s.staffWork?.away||r.students[st.id]>=r.chapter)return {error:'읽기 보완이 필요한 출석 학생을 선택해 주세요.'};const slot=M.currentSlot(s);if(!['afternoon','specialist'].includes(slot.kind)||s.minute+20>slot.end||P.conflicts(s,s.day,s.minute,s.minute+20).length)return {error:'수업·약속과 겹치지 않는 20분이 필요합니다.'};M.advance(s,20);r.students[st.id]++;M.remember(s,st,book(d.classBook).title+'의 놓친 부분을 함께 읽었다.',1);return {ok:true};}
export function activity(s,text){const d=data(s),r=d.reading[d.classBook];if(!r?.chapter||String(text).trim().length<8)return {error:'읽은 부분을 바탕으로 학생들이 만든 결과를 적어 주세요.'};if(d.activities.some(x=>x.day===s.day&&x.bookId===d.classBook&&x.chapter===r.chapter))return {error:'이 장의 오늘 활동은 이미 기록했습니다.'};d.activities.push({bookId:d.classBook,chapter:r.chapter,day:s.day,date:M.stamp(s),text:String(text).trim().slice(0,1000)});return {ok:true};}
export function valid(s){const d=s.libraryLife;if(d==null)return true;return d.schema===1&&d.stock&&Array.isArray(d.loans)&&d.loans.length<=5000&&d.loans.every(l=>book(l.bookId)&&Number.isInteger(l.count)&&l.count>0&&l.count<=28&&typeof l.returned==='boolean')&&BOOKS.every(b=>Number.isInteger(d.stock[b.id])&&d.stock[b.id]>=0&&available(s,b.id)>=0)&&(!d.classBook||book(d.classBook))&&d.reading&&Object.entries(d.reading).every(([id,r])=>book(id)&&Number.isInteger(r.chapter)&&r.chapter>=0&&r.chapter<=4&&r.students)&&Array.isArray(d.activities)&&Array.isArray(d.history);}
